#pragma once
#include <cstdint>
#include <map>
#include <vector>

namespace snabf {
struct RotationTerm {
  unsigned diagonal, baby, giant;
  bool operator==(const RotationTerm &) const = default;
};
// H_s is generated by stride in Z_(N/2). Order and index are b_v and
// g_v, not the counts of actually occupied rotations.
struct TowerSplit {
  unsigned rung, stride, order, index;
};
struct SubgroupRoute {
  unsigned towerIndex, subgroupStride, babyStride;
  std::vector<RotationTerm> terms;
  std::vector<unsigned> babyRotations, giantRotations;
  std::vector<std::uint64_t> galoisKeys;
  std::vector<TowerSplit> splits; // First is the executable representative.
  std::map<unsigned, std::vector<unsigned>> cosets; // gamma -> occupied d
};
std::uint64_t rotationElement(unsigned offset, unsigned logN);
unsigned rotationDepth(const SubgroupRoute &);
// The caller resolves packing first. Empty support is the zero map; {0}
// multiplies by a single diagonal. Neither requires a rotation key.
std::vector<SubgroupRoute>
enumerateSubgroupRoutes(unsigned logN,
                        const std::vector<std::int64_t> &offsets);
std::vector<SubgroupRoute>
executableRoutes(unsigned logN, const std::vector<std::int64_t> &offsets,
                 bool foldEquivalent = true);
} // namespace snabf
